      "replace": "def get_terminal_width() -> int:
	"""Get terminal width, default to 80 if unable to detect.

	If the COLUMNS environment variable is set to a positive integer, it will be used
	as the width. This is useful in environments where the terminal size cannot be
	queried (e.g., CI runners) but the width is known.
	"""
	# Prefer explicit COLUMNS env var if it looks like an integer
	cols_env = os.getenv("COLUMNS")
	if cols_env and cols_env.isdigit():
		return int(cols_env)
	try:
		return os.get_terminal_size().columns
	except (AttributeError, OSError):
		return 80"
