  "test": "import os
import pytest
from browser_use.sandbox.sandbox import get_terminal_width


def test_get_terminal_width_uses_columns_env(monkeypatch):
    # Ensure os.get_terminal_size raises to trigger fallback
    monkeypatch.setattr('os.get_terminal_size', lambda: (_ for _ in ()).throw(OSError()))
    monkeypatch.setenv('COLUMNS', '123')
    assert get_terminal_width() == 123


def test_get_terminal_width_falls_back_to_os(monkeypatch):
    # Provide a fake terminal size
    class DummySize:
        columns = 85
    monkeypatch.setattr('os.get_terminal_size', lambda: DummySize())
    monkeypatch.delenv('COLUMNS', raising=False)
    assert get_terminal_width() == 85


def test_get_terminal_width_defaults_when_no_info(monkeypatch):
    # Both env var absent and get_terminal_size fails
    monkeypatch.setattr('os.get_terminal_size', lambda: (_ for _ in ()).throw(OSError()))
    monkeypatch.delenv('COLUMNS', raising=False)
    assert get_terminal_width() == 80"
